{
     "title": "CSCI-536: Information Retrieval Foundations",
     "learningObjectives": [
       "Define and explain the core components of a search engine pipeline, including indexing, retrieval, and ranking.",
       "Compare traditional statistical retrieval models (TF-IDF, BM25) with modern neural retrieval techniques and their respective strengths.",
       "Apply standard evaluation metrics to assess search engine performance and identify common failure modes like data leakage or distribution shift."
     ],
     "beats": [
       {
         "title": "Search Engine Pipeline Overview",
         "claim": "A search engine pipeline consists of indexing, retrieval, and ranking stages that transform raw documents into ranked results for user queries.",
         "example": "When a user searches for 'climate change policies', the system first retrieves relevant documents from an index, then ranks them based on relevance before displaying the top results.",
         "visualDirection": "Display a horizontal flowchart with three labeled boxes: 'Query Input', 'Index & Retrieval', and 'Ranking & Output', connected by arrows indicating data flow.",
         "sourceIds": ["rit-csci-536"]
       },
       {
         "title": "Traditional Retrieval Models",
         "claim": "Traditional retrieval models like TF-IDF and BM25 calculate document relevance using statistical measures of term frequency and inverse document frequency.",
         "example": "TF-IDF assigns higher scores to terms that appear frequently in a specific document but rarely across the entire corpus, while BM25 adjusts for document length and term saturation.",
         "visualDirection": "Show a side-by-side comparison table listing 'TF-IDF' and 'BM25', with columns for 'Core Mechanism', 'Key Formula Components', and 'Typical Use Case'.",
         "sourceIds": ["rit-csci-536"]
       },
       {
         "title": "Modern Neural Retrieval",
         "claim": "Modern retrieval techniques employ neural reranking and retrieval models that use deep learning to capture semantic meaning and contextual relationships in text.",
         "example": "A neural reranker re-scores initially retrieved documents by analyzing query-document interactions through transformer-based architectures, improving relevance for complex or ambiguous queries.",
         "visualDirection": "Illustrate a two-stage pipeline: a traditional retriever outputs a candidate set, which is then passed to a neural reranker that outputs a refined ranked list.",
         "sourceIds": ["rit-csci-536"]
       },
       {
         "title": "Search Interfaces",
         "claim": "Search interfaces design how users interact with retrieval systems, balancing simplicity with advanced features like autocomplete, filters, and conversational prompts.",
         "example": "A conversational IR interface allows users to ask natural language questions, while an enterprise search interface provides faceted navigation and role-based access controls.",
         "visualDirection": "Display mockups of two search interfaces: one with a simple text box and autocomplete dropdown, and another with a chat-style prompt and structured filters.",
         "sourceIds": ["rit-csci-536"]
       },
       {
         "title": "Search Engine Evaluation",
         "claim": "Search engine evaluation uses standardized metrics to measure retrieval quality, ensuring that improvements align with user needs and system constraints.",
         "example": "Precision, recall, and mean average precision (MAP) quantify how many relevant documents appear in the top results, while user satisfaction surveys assess perceived usefulness.",
         "visualDirection": "Present a bar chart comparing precision and recall scores across three different retrieval models, with a legend indicating model names.",
         "sourceIds": ["rit-csci-536"]
       },
       {
         "title": "Search Applications",
         "claim": "Search applications extend beyond basic retrieval to include conversational IR, enterprise search, and domain-specific systems that integrate with broader software ecosystems.",
         "example": "Conversational IR systems maintain dialogue state and context to answer follow-up questions, while enterprise search integrates with CRM and document management platforms.",
         "visualDirection": "Create a Venn diagram showing overlapping circles for 'Conversational IR', 'Enterprise Search', and 'Domain-Specific Search', with intersection labels indicating shared features like context awareness and integration capabilities.",
         "sourceIds": ["rit-csci-536"]
       },
       {
         "title": "Machine Learning Workflows in IR",
         "claim": "Machine learning workflows for information retrieval separate data preparation, training, validation, and testing to prevent data leakage and ensure model generalization.",
         "example": "Preprocessing steps like tokenization and vectorization are fitted only on training data, while cross-validation ensures consistent evaluation across multiple data splits.",
         "visualDirection": "Show a sequential diagram of a machine learning pipeline with labeled stages: 'Data Preparation', 'Training', 'Validation', 'Testing', and 'Model Selection', with arrows indicating forward flow.",
         "sourceIds": ["scikit-learn-user-guide"]
       },
       {
         "title": "Evaluation Metrics and Error Analysis",
         "claim": "Evaluation metrics must match the task and the cost of different errors, and common failure modes like leakage, distribution shift, and overfitting can invalidate results.",
         "example": "Using accuracy for ranking tasks often masks poor performance on long-tail queries, while distribution shift between training and test data reduces model reliability in production.",
         "visualDirection": "Display a checklist graphic with items like 'Metric-Task Alignment', 'Leakage Prevention', 'Distribution Shift Detection', and 'Overfitting Monitoring', each with a checkbox.",
         "sourceIds": ["scikit-learn-user-guide"]
       },
       {
         "title": "Research Topics and Experiment Design",
         "claim": "Current IR research focuses on improving retrieval accuracy, reducing latency, and developing robust systems that handle uncertainty and fairness constraints.",
         "example": "Researchers design experiments to compare neural reranking strategies under varying query complexity, measuring improvements in MAP and latency while monitoring for bias in ranked results.",
         "visualDirection": "Present a template for an experiment design card with fields for 'Hypothesis', 'Variables', 'Metrics', 'Constraints', and 'Expected Outcomes', formatted as a structured form.",
         "sourceIds": ["rit-csci-536", "nist-ai-rmf"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "A practical analysis checklist ensures that search engine components are evaluated for correctness, efficiency, and alignment with user and system requirements before deployment.",
         "example": "Instructors and developers use the checklist to verify that indexing covers all required fields, retrieval models are tuned for the target domain, and evaluation metrics reflect real-world performance.",
         "visualDirection": "Show a printable checklist graphic with sections for 'Indexing Verification', 'Retrieval Tuning', 'Evaluation Validation', and 'Deployment Readiness', each containing three actionable items.",
         "sourceIds": ["rit-csci-536", "scikit-learn-user-guide"]
       }
     ]
   }
